1	export interface Accept {
2	  type: string
3	  params: Record<string, string>
4	  q: number
5	}
6	
7	const isWhitespace = (char: number): boolean =>
8	  char === 32 || char === 9 || char === 10 || char === 13
9	
10	const consumeWhitespace = (acceptHeader: string, startIndex: number): number => {
11	  while (startIndex < acceptHeader.length) {
12	    if (!isWhitespace(acceptHeader.charCodeAt(startIndex))) {
13	      break
14	    }
