      const res = await app.request('/json', {
        headers: { 'Accept-Encoding': 'br' },
      })
      expect(res.headers.get('Content-Encoding')).toBe('br')
    })

    it('should not compress with brotli when contentTypeFilter does not match', async () => {
      const res = await app.request('/text', {
        headers: { 'Accept-Encoding': 'br' },
      })
      expect(res.headers.get('Content-Encoding')).toBeNull()
    })
  })

  describe('Brotli threshold', () => {
    const app = new Hono()
    app.use('*', compress({ threshold: 2048 }))
    app.get('/below', (c) => {
      c.header('Content-Type', 'text/plain')
      c.header('Content-Length', '1024')
      return c.text('a'.repeat(1024))
    })

    it('should not compress with brotli when Content-Length is below threshold', async () => {
      const res = await app.request('/below', {
        headers: { 'Accept-Encoding': 'br' },
      })
      expect(res.headers.get('Content-Encoding')).toBeNull()
    })
  })
})

